{
  "name": "2026-07-09-grok-4-3-cursor",
  "private": true,
  "version": "0.0.0",
  "packageManager": "pnpm@10.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc && vite build",
    "preview": "vite preview"
  },
  "devDependencies": {
    "@types/node": "^26.1.1",
    "typescript": "~6.0.2",
