:root {
  --felt: oklch(0.18 0.045 285);
  --panel: oklch(0.24 0.038 282);
  --panel-2: oklch(0.28 0.032 280);
  --ink: oklch(0.95 0.018 95);
  --muted: oklch(0.72 0.03 280);
  --line: oklch(0.36 0.03 280);
  --celadon: #3dba8a;
  --cobalt: #4d7cff;
  --coral: #e85a4a;
  --ease: cubic-bezier(0.19, 1, 0.22, 1);
}

.app {
  height: 100%;
  display: grid;
  grid-template-columns: minmax(240px, 280px) minmax(0, 1fr) minmax(280px, 340px);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas:
    'top top top'
    'presets presets presets'
    'left stage right';
  background: var(--felt);
  color: var(--ink);
  font-family: Outfit, system-ui, sans-serif;
  font-size: 14px;
}

.top {
  grid-area: top;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 18px 4px;
}

h1 {
  margin: 0;
  font-family: Fraunces, Georgia, serif;
  font-size: clamp(1.4rem, 2vw, 1.85rem);
  font-weight: 600;
  letter-spacing: -0.02em;
  text-wrap: balance;
}

.transport {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

button {
  appearance: none;
  border: 0;
  background: var(--panel-2);
  color: var(--ink);
  padding: 7px 12px;
  border-radius: 999px;
  cursor: pointer;
  transition: background 140ms var(--ease), transform 140ms var(--ease);
}

button:hover {
  background: oklch(0.34 0.03 280);
}

button:active {
  transform: scale(0.97);
}

button.primary {
  background: var(--celadon);
  color: oklch(0.18 0.04 155);
}

button.ghost {
  background: transparent;
  padding: 4px 8px;
  color: var(--muted);
}

.speed {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  padding-left: 8px;
}

.speed span {
  font-family: 'IBM Plex Mono', ui-monospace, monospace;
  font-size: 12px;
  min-width: 3.2em;
  color: var(--ink);
}

.presets {
  grid-area: presets;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 4px 18px 10px;
}

.chip {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--muted);
  padding: 5px 11px;
}

.chip.on {
  border-color: var(--celadon);
  color: var(--ink);
  background: oklch(0.28 0.04 155);
}

.left,
.right {
  overflow: auto;
  padding: 0 14px 18px;
}

.left {
  grid-area: left;
  border-right: 1px solid var(--line);
}

.right {
  grid-area: right;
  border-left: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.stage {
  grid-area: stage;
  position: relative;
  min-height: 0;
}

.garden {
  display: block;
  width: 100%;
  height: 100%;
  cursor: grab;
  touch-action: none;
}

.garden:active {
  cursor: grabbing;
}

.live {
  position: absolute;
  left: 16px;
  bottom: 14px;
  display: flex;
  gap: 10px;
  font-family: 'IBM Plex Mono', ui-monospace, monospace;
  font-size: 12px;
  pointer-events: none;
}

.live span {
  padding: 3px 8px;
  border-radius: 999px;
  background: oklch(0.2 0.04 285 / 0.72);
}

.live .fruit { color: var(--celadon); }
.live .blue { color: var(--cobalt); }
.live .red { color: var(--coral); }
.live .time { color: var(--muted); }

.control-group {
  margin-bottom: 18px;
}

.control-group h2,
.inspector h2,
.charts h2 {
  margin: 0 0 4px;
  font-size: 13px;
  font-weight: 600;
}

.caption {
  margin: 0 0 10px;
  color: var(--muted);
  font-size: 12px;
}

.knob {
  display: grid;
  gap: 4px;
  margin-bottom: 10px;
}

.knob-row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
}

.knob-value {
  font-family: 'IBM Plex Mono', ui-monospace, monospace;
  color: var(--muted);
}

input[type='range'] {
  appearance: none;
  width: 100%;
  height: 4px;
  border-radius: 999px;
  background: var(--line);
  outline: none;
}

input[type='range']::-webkit-slider-thumb {
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--celadon);
  cursor: pointer;
}

input[type='range']::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border: 0;
  border-radius: 50%;
  background: var(--celadon);
  cursor: pointer;
}

.inspector {
  background: var(--panel);
  border-radius: 12px;
  padding: 12px;
}

.inspector.empty {
  color: var(--muted);
}

.inspector.empty p {
  margin: 0;
}

.inspector header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.swatch {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.inspector dl {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 12px;
  margin: 0;
}

.inspector dt {
  color: var(--muted);
}

.inspector dd {
  margin: 0;
  font-family: 'IBM Plex Mono', ui-monospace, monospace;
  text-align: right;
}

.meter {
  grid-column: 1 / -1;
  height: 4px;
  border-radius: 999px;
  background: var(--line);
  margin: 2px 0 8px;
}

.meter span {
  display: block;
  height: 100%;
  border-radius: inherit;
}

.charts section {
  margin-bottom: 14px;
}

.headline {
  margin: 0 0 8px;
  font-size: 14px;
}

.charts ul {
  margin: 0;
  padding-left: 16px;
  color: var(--muted);
}

.chart-svg {
  width: 100%;
  height: auto;
  display: block;
}

.chart-svg .axis {
  fill: var(--muted);
  font-size: 9px;
  font-family: 'IBM Plex Mono', ui-monospace, monospace;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  margin-top: 6px;
  font-size: 11px;
  color: var(--muted);
}

.legend i {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-right: 5px;
}

.legend em {
  font-style: normal;
  opacity: 0.65;
}

@media (max-width: 980px) {
  .app {
    grid-template-columns: 1fr;
