args.command:
pnpm exec tsx -e '
import { Engine } from "./src/sim/engine.ts"
import { DEFAULT_PARAMS } from "./src/sim/params.ts"
import { movingAverage, findPeaks, mean, bestLag } from "./src/sim/analysis.ts"

function score(label, params, seconds=2000) {
  const e = new Engine(params)
  e.run(seconds)
  const s = e.history.samples
  const from = Math.floor(s.length * 0.12)
  const body = s.slice(from)
  const blue = body.map(x => x.blue)
  const red = body.map(x => x.red)
  const win = Math.max(3, Math.round(body.length / 40))
  const blueS = movingAverage(blue, win)
  const redS = movingAverage(red, win)
  const bm = mean(blue), rm = mean(red)
  const bw = findPeaks(blueS, Math.max(2.5, bm * 0.28)).length
  const rw = findPeaks(redS, Math.max(1.8, rm * 0.3)).length
  const dt = (body.at(-1).t - body[0].t) / Math.max(1, body.length-1)
  const lag = bestLag(blueS, redS, Math.floor(body.length/3))
  const flag = e.world.counts.blue===0 ? " BLUE-OUT" : e.world.counts.red===0 ? " RED-OUT" : ""
  console.log(label.padEnd(36),
